import{_ as p,a0 as e,w as o,s as r,I as n,x as u,a1 as l,A as s,ao as b}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const O=JSON.parse('{"title":"官方的 Ubuntu 精簡 ISO 真的“精簡”嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"官方的 Ubuntu 精簡 ISO 真的“精簡”嗎？ | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"官方的 Ubuntu 精簡 ISO 真的“精簡”嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"官方的 Ubuntu 精簡 ISO 真的“精簡”嗎？ | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230408.1 ⭐️⭐️ Is Official Ubuntu Mini ISO Truly Minimal A Test Drive","title":"官方的 Ubuntu 精簡 ISO 真的“精簡”嗎？","tag":"202304","desc":""},"relativePath":"202304/20230408.1 ⭐️⭐️ Is Official Ubuntu Mini ISO Truly Minimal A Test Drive.md","filePath":"[post].md"}'),m={name:"202304/20230408.1 ⭐️⭐️ Is Official Ubuntu Mini ISO Truly Minimal A Test Drive.md"};function a(d,t,U,f,g,I){const i=e("Link");return o(),r("div",null,[t[24]||(t[24]=n("h1",{id:"官方的-ubuntu-精簡-iso-真的-精簡-嗎",tabindex:"-1"},[u("官方的 Ubuntu 精簡 ISO 真的“精簡”嗎？ "),n("a",{class:"header-anchor",href:"#官方的-ubuntu-精簡-iso-真的-精簡-嗎","aria-label":"Permalink to “官方的 Ubuntu 精簡 ISO 真的“精簡”嗎？”"},"​")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/27/213525ymlmxicpt3ctmlti.jpg",alt:""})],-1)),t[26]||(t[26]=n("blockquote",null,[n("p",null,"Ubuntu 23.04 “Lunar Lobster” 新推出的精簡安裝程序到底有多精簡呢？一起來看看吧。")],-1)),n("p",null,[t[1]||(t[1]=u("幾周前，Canonical/Ubuntu 開發者 ",-1)),l(i,{href:"https://linux.cn/article-15588-1.html"},{default:s(()=>[...t[0]||(t[0]=[u("確認了",-1)])]),_:1}),t[2]||(t[2]=u(" Ubuntu 23.04 Lunar Lobster 將引入官方的精簡版安裝程序。對於那些等待 Ubuntu Linux 官方精簡安裝程序的用户來説，這是個好消息，因為 Canonical/Ubuntu 此前從未對任何精簡 ISO 鏡像提供官方支持。",-1))]),t[27]||(t[27]=b('<p>雖然在 Ubuntu 18.04 時期有一些非官方性質的舊版精簡 ISO 鏡像，但它們都已經停止維護。鑑於 Ubuntu Linux 的熱門程度，這種無法獲取精簡安裝程序的情況已阻礙部分用户的選擇。</p><p>正如公告所言，Canonical 現在已經為 Ubuntu 23.04 Lunar Lobster 版本推出了官方精簡安裝程序，這也意味着那些希望安裝輕量版本 Ubuntu Linux 用户的等待終於結束了。</p><p>我試運行了該 <strong>測試版</strong> ISO 鏡像（LCTT 校注：本文原文發佈於 Ubuntu 23.04 正式版發佈之前）。下面是我發現的一些東西。</p><p>在最新的 Beta 版本中，官方的 Ubuntu 精簡版 ISO 安裝程序現已提供試用。“Lunar Lobster”版本的官方 ISO 鏡像大小為 113 MB，這確實很小。</p><p>當你首次啓動該精簡 ISO 時，你將可以選擇兩個主要選項 —— 針對服務器版本和桌面版本的安裝選項。目前我用於試運行的測試版精簡 ISO 顯示了 Ubuntu 22.04 LTS 和 Ubuntu 22.10 Kinetic Kudu —— 於去年發佈。不過，先暫時忽略這些文本標識吧。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/04/Ubuntu-minimal-install-first-menu.jpg" alt="Ubuntu 精簡安裝 - 第一個菜單"></p><p>我首先嚐試安裝桌面版本。令人驚訝的是，它運行了一個下載器，以獲取用於標準桌面安裝的所有軟件包。精簡桌面版的選項需要從互聯網下載超過 3GB 的軟件包，而且用時很長。考慮到我的位置與 Ubuntu 服務器狀態，我的下載測試花費了大量時間。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/04/Ubuntu-mini-installer-downloads-the-desktop-itself-online.jpg" alt="Ubuntu 精簡安裝程序在線下載桌面本身"></p><p>如果你將使用精簡 Ubuntu ISO 安裝桌面所需的時間與精力與常規下載進行比較，那精簡版反而慢許多，並佔用大量系統資源。舉個例子，在安裝程序運行時，下載的完整 Ubuntu 桌面版也同時存儲於內存當中。</p><p>因此，精簡版的最小內存大小要求為 8GB。如果你沒有 8GB 內存，你就無法運行該安裝程序。而另一邊，如果你藉助標準的 torrent 文件下載 Ubuntu 桌面版，那麼用於啓動安裝程序的最小內存要求則為 4GB。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/04/Mandatory-requirement-of-8GB-RAM-for-Ubuntu-mini-ISO.jpg" alt="Ubuntu 精簡版 ISO 的強制性 8GB RAM 要求"></p><p>下載完成後，安裝程序將啓動<ruby>立付<rt>Live</rt></ruby> Ubuntu 系統，在這裏，你將可以和平常一樣安裝帶有 GNOME 桌面的 Ubuntu 桌面版。這根本沒有區別。</p><p>來到服務器選項，我在精簡安裝程序裏選擇了 Ubuntu 22.04 LTS 服務器版本。令我驚訝的是，服務器安裝選項也需要至少 8GB 內存才能開始安裝。基於該版本，它下載了約 1.8GB 的軟件包。之後，它啓動了正常的 Ubuntu 服務器版安裝程序。這與常規的服務器版安裝過程也是毫無區別。</p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/04/Ubuntu-mini-ISO-server-option-is-just-regular-server-installation.jpg" alt="Ubuntu 精簡 ISO - 服務器選項只是常規的服務器安裝"></p><p><img src="https://debugpointnews.com/wp-content/uploads/2023/04/Ubuntu-mini-ISO-server-install-takes-around-7GB-of-storage.jpg" alt="Ubuntu 精簡 ISO - 服務器安裝大約佔用 7GB 存儲"></p><p>綜上可知，精簡版桌面安裝程序僅僅只是一個下載完整桌面版或服務器版鏡像的 CLI 前端界面，僅此而已。這款安裝程序的主要用途可能是 Ubuntu 桌面版或服務器版的聯網安裝。但，再次強調，你需要穩定的網絡連接，以便下載所需內容。</p>',16)),n("p",null,[t[4]||(t[4]=u("與之相似的是，Xubuntu 團隊在幾周前 ",-1)),l(i,{href:"https://www.debugpoint.com/xubuntu-minimal/"},{default:s(()=>[...t[3]||(t[3]=[u("提供了",-1)])]),_:1}),t[5]||(t[5]=u(" 精簡版 ISO，它只包含基本的 Ubuntu，以及不含任何額外程序的原生 Xfce 桌面。",-1))]),t[28]||(t[28]=n("p",null,"也就是説，這款安裝程序恐怕和你從名字裏所想的不太一樣。如果他們能提供一款僅包含必要的 Ubuntu 組件，且不含桌面環境、Snap 等要素的“真·精簡 ISO”，那會更好；就像不含任何桌面組件的原生 Arch 安裝那樣。",-1)),n("p",null,[t[7]||(t[7]=u("你可以從 ",-1)),l(i,{href:"https://cdimages.ubuntu.com/ubuntu-mini-iso/daily-live/current/"},{default:s(()=>[...t[6]||(t[6]=[u("該頁面",-1)])]),_:1}),t[8]||(t[8]=u(" 下載精簡 ISO。",-1))]),t[29]||(t[29]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=u("via: ",-1)),l(i,{href:"https://debugpointnews.com/ubuntu-minimal-test-drive/"},{default:s(()=>[...t[9]||(t[9]=[u("https://debugpointnews.com/ubuntu-minimal-test-drive/",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=u("作者：",-1)),l(i,{href:"https://debugpointnews.com/author/dpicubegmail-com/"},{default:s(()=>[...t[11]||(t[11]=[u("arindam",-1)])]),_:1}),t[16]||(t[16]=u(" 選題：",-1)),l(i,{href:"https://github.com/lkxed/"},{default:s(()=>[...t[12]||(t[12]=[u("lkxed",-1)])]),_:1}),t[17]||(t[17]=u(" 譯者：",-1)),l(i,{href:"https://github.com/imgradeone"},{default:s(()=>[...t[13]||(t[13]=[u("imgradeone",-1)])]),_:1}),t[18]||(t[18]=u(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[14]||(t[14]=[u("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=u("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[19]||(t[19]=[u("LCTT",-1)])]),_:1}),t[22]||(t[22]=u(" 原創編譯，",-1)),l(i,{href:"https://linux.cn/"},{default:s(()=>[...t[20]||(t[20]=[u("Linux中國",-1)])]),_:1}),t[23]||(t[23]=u(" 榮譽推出",-1))])])}const L=p(m,[["render",a]]);export{O as __pageData,L as default};
